export const INTERVALS = {'1H':60,'4H':240,'1D':1440,'1W':10080};
export function mergeCandles(existing,incoming){const map=new Map(existing.map(c=>[c.time,c]));for(const c of incoming){if(Number.isFinite(c.time)&&[c.open,c.high,c.low,c.close].every(n=>Number.isFinite(n)&&n>0))map.set(c.time,c);}return [...map.values()].sort((a,b)=>a.time-b.time).slice(-120);}
export function updateBook(current,updates,depth=10){const map=new Map(current.map(x=>[x.price,x.qty]));for(const x of updates){if(Number.isFinite(x.price)&&Number.isFinite(x.qty)&&x.price>0&&x.qty>=0){if(x.qty===0)map.delete(x.price);else map.set(x.price,x.qty);}}return [...map].map(([price,qty])=>({price,qty}));}
export function connectMarket({symbols,symbol,interval,onData,onStatus,Socket=globalThis.WebSocket,fetcher=globalThis.fetch}){
 let socket,closed=false,retry,watchdog,attempt=0,lastMessage=0,generation=0,controller;
 let state={tickers:{},candles:[],bids:[],asks:[],trades:[],historyError:false,errors:{}};
 const emit=()=>onData({...state});
 const params=(channel,s=symbol,i=interval)=>({channel,symbol:channel==='ticker'?symbols:[s],...(channel==='book'?{depth:10}:{}),...(channel==='ohlc'?{interval:i}:{} )});
 const send=(method,channel,s,i)=>{if(socket?.readyState===1)socket.send(JSON.stringify({method,params:{...params(channel,s,i),...(method==='subscribe'?{snapshot:true}:{})}}));};
 async function history(){const token=++generation;controller?.abort();controller=new AbortController();try{const response=await fetcher('/api/market-data?symbol='+encodeURIComponent(symbol)+'&interval='+interval,{signal:controller.signal});if(!response.ok)throw Error();const body=await response.json();if(token===generation&&!closed){state.candles=mergeCandles(body.candles,state.candles);state.historyError=false;emit();}}catch(error){if(error.name!=='AbortError'&&token===generation&&!closed){state.historyError=true;emit();}}}
 function open(){if(closed)return;onStatus(attempt?'Reconnecting':'Connecting');lastMessage=Date.now();socket=new Socket('wss://ws.kraken.com/v2');socket.onopen=()=>{lastMessage=Date.now();send('subscribe','ticker');for(const channel of ['ohlc','book','trade'])send('subscribe',channel);history();};socket.onmessage=event=>{if(closed)return;lastMessage=Date.now();let m;try{m=JSON.parse(event.data);}catch{return;}if(m.success===false){state.errors[m.result?.channel||'subscription']=m.error||'Subscription unavailable';emit();return;}if(!Array.isArray(m.data)||!['ticker','ohlc','book','trade'].includes(m.channel))return;attempt=0;onStatus('Live');if(m.channel==='ticker'){for(const t of m.data)if(symbols.includes(t.symbol))state.tickers[t.symbol]=t;}else{const data=m.data.filter(x=>x.symbol===symbol);if(!data.length)return;if(m.channel==='ohlc')state.candles=mergeCandles(state.candles,data.filter(x=>x.interval===interval).map(c=>({...c,time:Date.parse(c.interval_begin)/1000})));if(m.channel==='book'){for(const b of data){state.bids=updateBook(m.type==='snapshot'?[]:state.bids,b.bids||[]).sort((a,b)=>b.price-a.price).slice(0,10);state.asks=updateBook(m.type==='snapshot'?[]:state.asks,b.asks||[]).sort((a,b)=>a.price-b.price).slice(0,10);}}if(m.channel==='trade'){const trades=m.type==='snapshot'?data:[...state.trades,...data];state.trades=[...new Map(trades.map(t=>[t.trade_id,t])).values()].sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp)).slice(0,20);}}emit();};socket.onerror=()=>socket.close();socket.onclose=()=>{if(closed)return;state.bids=[];state.asks=[];state.trades=[];emit();onStatus('Reconnecting · prices may be stale');retry=setTimeout(open,Math.min(30000,1000*2**Math.min(attempt++,5)));};}
 watchdog=setInterval(()=>{if([0,1].includes(socket?.readyState)&&Date.now()-lastMessage>20000){onStatus('Stale · reconnecting');socket.close();}},5000);open();
 return {select(nextSymbol,nextInterval){for(const c of ['ohlc','book','trade'])send('unsubscribe',c);symbol=nextSymbol;interval=nextInterval;state={...state,candles:[],bids:[],asks:[],trades:[],historyError:false,errors:{}};emit();for(const c of ['ohlc','book','trade'])send('subscribe',c);history();},close(){closed=true;generation++;controller?.abort();clearTimeout(retry);clearInterval(watchdog);socket?.close();}};
}
